using UnityEngine;
namespace FalloutPort {
public class PortSurvival : MonoBehaviour {
 public float health=100,stamina=100; public int stimpaks=2,caps,cacheMask; public bool challengeActive,challengeDone,practiceIssued; public int targetsHit; public float challengeTime; public float hurtUntil,hitUntil; public bool Dead=>health<=0;
 PortGame game; float lastHeal=-100; public static PortSurvival Instance;
 void Awake(){Instance=this;game=GetComponent<PortGame>();}
 void Update(){if(Time.timeScale==0)return;stamina=Mathf.Min(100,stamina+Time.deltaTime*12);if(challengeActive){challengeTime-=Time.deltaTime;if(challengeTime<=0){challengeActive=false;game.notice="Range time expired. Use the security console to retry.";}}}
 public bool Sprint(float dt){if(stamina<dt*30)return false;stamina=Mathf.Max(0,stamina-dt*30);return true;}
 public void Damage(float amount){if(Dead||game.paused||game.dialogueOpen||Time.time<hurtUntil-.4f)return;health=Mathf.Max(0,health-amount);hurtUntil=Time.time+.65f;game.Sound("ui");if(Dead){game.notice="You were overwhelmed. Load a save or start again.";game.menu.DeathMenu();}}
 public void Heal(){if(Dead||health>=100||stimpaks<=0||Time.time<lastHeal+1)return;lastHeal=Time.time;stimpaks--;health=Mathf.Min(100,health+45);game.Sound("quest");game.notice="Stimpak used · +45 HP";}
 public void Loot(int index){int bit=1<<index;if((cacheMask&bit)!=0){game.notice="This cache is empty.";return;}cacheMask|=bit;if(index==0){stimpaks+=2;game.notice="Clinic supplies · 2 stimpaks acquired";}else if(index==1){game.reserve+=24;game.notice="Maintenance stash · 24 rounds acquired";}else{caps+=25;game.notice="Old tenant's cache · 25 caps acquired";}game.Sound("quest");}
 public void BeginChallenge(){if(!game.hasPistol){game.notice="Collect Doyle's pistol first.";return;}if(challengeDone){game.notice="Security qualification complete · reward already collected.";return;}challengeActive=true;targetsHit=0;challengeTime=30;foreach(var t in FindObjectsByType<PortRangeTarget>(FindObjectsSortMode.None))t.ResetTarget();if(!practiceIssued){game.reserve+=6;practiceIssued=true;}game.notice="SECURITY QUALIFICATION · hit all 3 targets in 30 seconds. Six practice rounds supplied.";}
 public void TargetHit(){if(!challengeActive)return;targetsHit++;if(targetsHit>=3){challengeActive=false;challengeDone=true;caps+=75;stimpaks+=2;game.reserve+=24;game.Sound("quest");game.notice="QUALIFIED · +75 caps, 2 stimpaks, 24 rounds";}}
 public void ResetRun(){lastHeal=-100;health=stamina=100;stimpaks=2;caps=cacheMask=targetsHit=0;challengeActive=challengeDone=practiceIssued=false;hurtUntil=hitUntil=0;}
 void OnGUI(){if(!game||game.menu.Visible)return;float scale=Mathf.Min(Screen.width/1280f,Screen.height/720f);GUI.matrix=Matrix4x4.TRS(Vector3.zero,Quaternion.identity,Vector3.one*scale);float w=Screen.width/scale,h=Screen.height/scale;var style=new GUIStyle(GUI.skin.label){fontSize=18};style.normal.textColor=new Color(.45f,1,.64f);GUI.Label(new Rect(30,h-151,650,26),"HP "+Mathf.CeilToInt(health)+"     AP "+Mathf.CeilToInt(stamina)+"     STIM "+stimpaks+" [Q / D-pad Up]     CAPS "+caps,style);GUI.color=new Color(.08f,.16f,.1f);GUI.DrawTexture(new Rect(30,h-122,200,7),Texture2D.whiteTexture);GUI.color=new Color(.25f,1,.55f);GUI.DrawTexture(new Rect(30,h-122,health*2,7),Texture2D.whiteTexture);GUI.color=Color.white;if(Time.time<hitUntil)GUI.Label(new Rect(w/2-8,h/2-12,30,30),"×",style);if(Time.time<hurtUntil){GUI.color=new Color(.7f,.02f,.01f,(hurtUntil-Time.time)*.22f);GUI.DrawTexture(new Rect(0,0,w,h),Texture2D.whiteTexture);GUI.color=Color.white;}if(challengeActive)GUI.Label(new Rect(w/2-180,125,500,32),"SECURITY QUALIFICATION  "+targetsHit+"/3   "+Mathf.CeilToInt(challengeTime)+"s",style);}
 }
}
